import { test } from "node:test";
import assert from "node:assert/strict";
import { oralAmendmentsFromNotes } from "./indicativeVotingList.ts";

test("an oral amendment under Miscellaneous is read with its markup", () => {
  const got = oralAmendmentsFromNotes([
    "<b><u>Miscellaneous</u></b>",
    "MEP Teodorescu will move the following oral amendment to article 4, § 5",
    "”Member States shall <b>remain subject</b> <s>are not</s> subject to liability.”",
    "<i>Generated by LAURUS</i>",
  ]);
  assert.deepEqual(got, [
    { mep: "Teodorescu", subject: "article 4, § 5", text: "Member States shall <b>remain subject</b> <s>are not</s> subject to liability." },
  ]);
});

test("a list without one gives none", () => {
  assert.deepEqual(oralAmendmentsFromNotes(["Requests for roll-call votes"]), []);
});
